INSERT INTO titles (id, "order", name, freq, parentId, nodeType) VALUES (171, 1, 'مقدمة هذه الطبعة', 'd', 99, 'content');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1654, 171, 1, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ', 0, 'مقدمة هذه الطبعة. (ص5)', '', '', 'بسم الله الرحمن الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1655, 171, 2, 'الحمدُ لله الذي جعل ذِكرَه عُدَّةً للمتقين، يتوصَّلون بها إلى خيرَيِ الدُّنيا والدِّين، وجُنَّةً واقيةً للمؤمنين، سهامَ الشياطين، وشرَّ إخوانهم المتمردين، من طوائف الخلقِ أجمعين.', 0, 'مقدمة هذه الطبعة. (ص5)', '', '', 'الحمد لله الذي جعل ذكره عدة للمتقين يتوصلون بها إلى خيري الدنيا والدين وجنة واقية للمؤمنين سهام الشياطين وشر إخوانهم المتمردين من طوائف الخلق أجمعين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1656, 171, 3, 'وصلَّى الله على خيرِ البشرِ، الذي أُنْزِلَ عليه: ﴿ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ ﴾ [العنكبوت: ٤٥]، فبيَّن للعباد من فضائل الأذكار، وما فيها من المنافع الكبار، والفوئد ذوات الأخطار، ما ملأ الأسفار، وتناقلته ألسن الرواة في جميع الأقطار، وكان العمل به في جميع الأعصار، وعلى مَن صاحبه ووالاه، وسلَّم تسليمًا كثيرًا لا يُدْرَكُ منتهاه، وبعدُ:', 0, 'مقدمة هذه الطبعة. (ص5)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1657, 171, 4, 'فهذه طبعةٌ مَزِيدةٌ لكتاب «مختصر النصيحة» الذي جَرَّدْتُ فيه نصوصَ الأذكار والأدعية؛ ليكون أسهلَ للناظر فيه، وأعونَ له على استحضارِه والعملِ بما فيه، ثُمَّ زِدتُ في هذه الطبعةِ بعضَ الفوائدِ المتعلقة بالذكر وفضائله، وكذا فوائد تتعلق بمفهوم الورد والحزب، وأهمية المداومة على الأوراد، وتوسَّعتُ قليلًا في بيان فضائل الأوراد المأثورة وأنواعها، وصيغ كُلٍّ منها.', 0, 'مقدمة هذه الطبعة. (ص5–6)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1658, 171, 5, 'والحمدُ لله رَبِّ العَالَمين', 0, 'مقدمة هذه الطبعة. (ص6)', '', '', 'والحمد لله رب العالمين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1659, 171, 6, 'محمد أحمد إسماعيل المقدم
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1008, 102, 1, 'الحمدُ لله نستعينه ونستغفره، ونعوذ بالله من شرور أنفسنا، من يهدِ الله فلا مُضِلَّ له، ومن يضلل فلا هاديَ له، وأشهدُ أن لا إله إلَّا الله، وأشهدُ أنَّ محمدًا عبدُه ورسولُه، أرسلَه بالحقِّ بشيرًا ونذيرًا بين يدي الساعةِ.', 0, 'مقدمة الطبعات السابقة. (ص7)', '', '', 'الحمد لله نستعينه ونستغفره ونعوذ بالله من شرور أنفسنا من يهد الله فلا مضل له ومن يضلل فلا هادي له وأشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله أرسله بالحق بشيرا ونذيرا بين يدي الساعة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1660, 102, 2, 'من يطع الله ورسوله فقد رشد، ومن يعصِ اللهَ ورسولَه فإنه لا يضر إلَّا نفسَه، ولا يَضُرُّ اللهَ شيئًا.', 0, 'مقدمة الطبعات السابقة. (ص7)', '', '', 'من يطع الله ورسوله فقد رشد ومن يعص الله ورسوله فإنه لا يضر إلا نفسه ولا يضر الله شيئا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1661, 102, 3, 'اللهمَّ صلِّ على محمدٍ عبدِكَ ورسولِك النبيِّ الأُمِّيِّ، وعلى آلِ محمدٍ وأزواجه وذريته، كما صلَّيتَ على إبراهيم وعلى آلِ إبراهيم، وبارِك على محمدٍ النبيِّ الأُمِّيِّ، وعلى آلِ محمد وأزواجه وذريته، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ في العالمين، إنَّك حميدٌ مجيد.', 0, 'مقدمة الطبعات السابقة. (ص7)', '', '', 'اللهم صل على محمد عبدك ورسولك النبي الأمي وعلى آل محمد وأزواجه وذريته كما صليت على إبراهيم وعلى آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد وأزواجه وذريته كما باركت على إبراهيم وعلى آل إبراهيم في العالمين إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1662, 102, 4, 'أمَّا بعدُ:', 0, 'مقدمة الطبعات السابقة. (ص8)', '', '', 'أما بعد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1663, 102, 5, 'فهذا مُختصر «النصيحة في الأذكار والأدعية الصحيحة» جَمَعَ أصحَّ الأدعيةِ والأذكار المجرَّدة في الأوقات والأحوال المختلفة، وجعلته كالمتن توطئةً لشرحه وبسطه في الطبعة الآتية للأصل التي ستتضمن إنْ شاء الله كثيرًا من الفوائد والأحكام والآداب الشرعية، بجانب تخريج كل حديثٍ تخريجًا دقيقًا ومُفصَّلًا، مع بيان مَنْ صَحَّحَهُ أو حَسَّنه، وذِكْرِ نَصِّه كاملًا محتويًا الفضائلَ على خلافِ ما كان في الطَّبْعاتِ السابقة، وهذا المختصر.', 0, 'مقدمة الطبعات السابقة. (ص8)', '', '', 'فهذا مختصر «النصيحة في الأذكار والأدعية الصحيحة» جمع أصح الأدعية والأذكار المجردة في الأوقات والأحوال المختلفة وجعلته كالمتن توطئة لشرحه وبسطه في الطبعة الآتية للأصل التي ستتضمن إن شاء الله كثيرا من الفوائد والأحكام والآداب الشرعية بجانب تخريج كل حديث تخريجا دقيقا ومفصلا مع بيان من صححه أو حسنه وذكر نصه كاملا محتويا الفضائل على خلاف ما كان في الطبعات السابقة وهذا المختصر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1664, 102, 6, 'وإنَّما تعجَّلْتُ إخراجَه بهذه الصورة المختصرة مبادرةً بالأعمال، وتسهيلًا على الحريصين على تيسير العمل بالأذكار الثابتة الواردة في السُّنَّةِ الشريفة.', 0, 'مقدمة الطبعات السابقة. (ص8)', '', '', 'وإنما تعجلت إخراجه بهذه الصورة المختصرة مبادرة بالأعمال وتسهيلا على الحريصين على تيسير العمل بالأذكار الثابتة الواردة في السنة الشريفة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1665, 102, 7, 'ولم آلُ جهدًا في التَّحرِّي عن صحَّةِ الأحاديث، والاستفادة من الملاحظات التي أبداها بعضُ الناصحين -جزاهم الله خيرًا- وما من جملةٍ مسطورةٍ في الكتابِ إلَّا وعليها -بفضل الله- دليلٌ من قرآن أو سنة ثابتة، أو أثر صحيح، ولا تخرج بحال عن أقوال أهل هذا العلم الشريف.', 0, 'مقدمة الطبعات السابقة. (ص8–9)', '', '', 'ولم آل جهدا في التحري عن صحة الأحاديث والاستفادة من الملاحظات التي أبداها بعض الناصحين -جزاهم الله خيرا- وما من جملة مسطورة في الكتاب إلا وعليها -بفضل الله- دليل من قرآن أو سنة ثابتة أو أثر صحيح ولا تخرج بحال عن أقوال أهل هذا العلم الشريف', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1666, 102, 8, 'تنبيه:', 0, '(ص9)', '', '', 'تنبيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1667, 102, 9, 'اعلم -رحمني الله وإيَّاك- أنَّه قد تَرِدُ أذكارٌ كثيرةٌ في وظيفةٍ واحدةٍ، يمكن الجمعُ بينها، فمَنْ وُفِّقَ للعمل بها كُلِّها فهي نعمةٌ من الله وفضلٌ، ومَنْ عجز عن جميعها فليقتصر من مختصراتها على قدرٍ يداومُ عليه، ولو كان ذكرًا واحدًا، وفضلُ الأكثر أكثر، والأوسطُ أقصد، وهو أجدر بأن يدومَ عليه.', 0, 'تنبيه: (ص9–10)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1668, 102, 10, 'وكُلُّ وظيفةٍ لا يمكنُ المواظبةُ على كثيرها، فقليلُها مع المداومةِ أفضلُ وأشدُّ تأثيرًا في القلب من كثيرها مع الفترة.', 0, 'تنبيه: (ص10)', '', '', 'وكل وظيفة لا يمكن المواظبة على كثيرها فقليلها مع المداومة أفضل وأشد تأثيرا في القلب من كثيرها مع الفترة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1669, 102, 11, 'وعليه أن يأتيَ ببعضٍ مرَّةً، وبالبعض الآخر مرَّةً أخرى؛ حتى يكون عاملًا بها جميعِها، غيرَ هاجرٍ لبعضها.', 0, 'تنبيه: (ص10)', '', '', 'وعليه أن يأتي ببعض مرة وبالبعض الآخر مرة أخرى حتى يكون عاملا بها جميعها غير هاجر لبعضها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1670, 102, 12, 'وأسألُ اللهَ العليَّ العظيمَ، وأتوسَّلُ إليه بأسمائه الحُسنى وصفاته العُليا، أن يجعله خالصًا لوجهه الكريم، نافعًا لعباده الصالحين، وأسأله سبحانه أن يمُنَّ علينا بالعفوِ والعافية، وحُسْنِ الخاتمة.', 0, 'مقدمة الطبعات السابقة. (ص10)', '', '', 'وأسأل الله العلي العظيم وأتوسل إليه بأسمائه الحسنى وصفاته العليا أن يجعله خالصا لوجهه الكريم نافعا لعباده الصالحين وأسأله سبحانه أن يمن علينا بالعفو والعافية وحسن الخاتمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1671, 102, 13, 'والحمدُ لله أوَّلًا وآخِرًا، وظاهرًا وباطنًا، وصلَّى الله وسلَّمَ وبارَكَ على عبدِه ورسولِه وخليلِه محمدٍ وعلى آلِه وصحبِه أجمعين.', 0, 'مقدمة الطبعات السابقة. (ص11)', '', '', 'والحمد لله أولا وآخرا وظاهرا وباطنا وصلى الله وسلم وبارك على عبده ورسوله وخليله محمد وعلى آله وصحبه أجمعين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1204, 102, 14, 'محمد أحمد إسماعيل المقدم
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1672, 104, 1, 'قال الله عز وجل: ﴿ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ﴾. [الأنفال: ٤٥]', 0, 'الأمر بالإكثار من ذكر الله تعالى وفضيلته. (ص13)', '', '', 'قال الله عز وجل ﴿ وٱذۡكروا ٱلله كثيرا لعلكمۡ تفۡلحون ﴾ الأنفال ٤٥', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1673, 104, 2, 'وقال سبحانه وتعالى: ﴿ إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ ﴾ إلى قوله تعالى: ﴿ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا ﴾ [الأحزاب: ٣٥].', 0, 'الأمر بالإكثار من ذكر الله تعالى وفضيلته. (ص13)', '', '', 'وقال سبحانه وتعالى ﴿ إن ٱلۡمسۡلمين وٱلۡمسۡلمت ﴾ إلى قوله تعالى ﴿ وٱلذكرين ٱلله كثيرا وٱلذكرت أعد ٱلله لهم مغۡفرة وأجۡرا عظيما ﴾ الأحزاب ٣٥', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1674, 104, 3, 'وقال تعالى: ﴿ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴾ [الأحزاب: ٤١، ٤٢]، قال عليُّ بنُ أبي طلحةَ، عن ابن عبَّاسٍ رضي الله عنهما في قوله تعالى: ﴿ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ﴾: «إنَّ الله لم يفرض على عباده فريضةً إلَّا جعل لها حدًّا معلومًا، ثُمَّ عذر أهلها في حالِ عذرٍ، غيرَ الذكر؛ فإنَّ الله لم يجعل له حدًّا ينتهي إليه، ولم يعذر أحدًا في تركه، إلَّا مغلوبًا على عقله؛ فقال: ﴿ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ ﴾ [النساء: ١٠٣]، بالليل والنهار، في البر والبحر، وفي السفر والحضر، والغِنَى والفقر، والصحة والسقم، والسر والعلانية، وعلى كُلِّ حالٍ، وقال: ﴿ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴾، فإذا فعلتم ذلك؛ صلَّى عليكم هو وملائكتُه».', 0, 'الأمر بالإكثار من ذكر الله تعالى وفضيلته. (ص13–14)', '', '', 'وقال تعالى ﴿ يأيها ٱلذين ءامنوا ٱذۡكروا ٱلله ذكۡرا كثيرا ٤١ وسبحوه بكۡرة وأصيلا ﴾ الأحزاب ٤١ ٤٢ قال علي بن أبي طلحة عن ابن عباس رضي الله عنهما في قوله تعالى ﴿ ٱذۡكروا ٱلله ذكۡرا كثيرا ﴾ «إن الله لم يفرض على عباده فريضة إلا جعل لها حدا معلوما ثم عذر أهلها في حال عذر غير الذكر فإن الله لم يجعل له حدا ينتهي إليه ولم يعذر أحدا في تركه إلا مغلوبا على عقله فقال ﴿ فٱذۡكروا ٱلله قيما وقعودا وعلى جنوبكمۡۚ ﴾ النساء ١٠٣ بالليل والنهار في البر والبحر وفي السفر والحضر والغنى والفقر والصحة والسقم والسر والعلانية وعلى كل حال وقال ﴿ وسبحوه بكۡرة وأصيلا ﴾ فإذا فعلتم ذلك صلى عليكم هو وملائكته»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1675, 104, 4, 'فضائل ذكر الله عز وجل', 0, '(ص15)', '', '', 'فضائل ذكر الله عز وجل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1676, 104, 5, 'ما أكثرَ الآياتِ والأحاديثَ التي تُرغِّب في ذكر الله سبحانه، وتُثْنِي على أهله أبلغ الثناء وأطيبه!', 0, 'فضائل ذكر الله عز وجل. (ص15)', '', '', 'ما أكثر الآيات والأحاديث التي ترغب في ذكر الله سبحانه وتثني على أهله أبلغ الثناء وأطيبه!', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1677, 104, 6, 'كقوله تعالى: ﴿ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴾ [الأحزاب: ٤١، ٤٢]، وقوله عز وجل: ﴿ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ ﴾ [البقرة: ١٥٢]، وقوله جل وعلا: ﴿ وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ ﴾ [الأعراف: ٢٠٥].', 0, 'فضائل ذكر الله عز وجل. (ص15)', '', '', 'كقوله تعالى ﴿ يأيها ٱلذين ءامنوا ٱذۡكروا ٱلله ذكۡرا كثيرا ٤١ وسبحوه بكۡرة وأصيلا ﴾ الأحزاب ٤١ ٤٢ وقوله عز وجل ﴿ فٱذۡكروني أذۡكرۡكمۡ ﴾ البقرة ١٥٢ وقوله جل وعلا ﴿ وٱذۡكر ربك في نفۡسك تضرعا وخيفة ودون ٱلۡجهۡر من ٱلۡقوۡل بٱلۡغدو وٱلۡأصال ولا تكن من ٱلۡغفلين ﴾ الأعراف ٢٠٥', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1678, 104, 7, 'عن أبي هريرة رضي الله عنه: قال رسولُ الله ﷺ: «يقول اللهُ عز وجل: أنا مع عبدي ما ذَكَرني، وتحرَّكَتْ بي شفتاه».', 0, 'فضائل ذكر الله عز وجل. (ص15)', '', '', 'عن أبي هريرة رضي الله عنه قال رسول الله «يقول الله عز وجل أنا مع عبدي ما ذكرني وتحركت بي شفتاه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1679, 104, 8, 'وعن أبي الدرداء رضي الله عنه أنَّ رسول الله ﷺ قال: «ألا أخبركم بخيرِ أعمالِكم، وأرفعِها في درجاتِكم، وأزكاها عند مَليكِكم، وخيرٍ لكم من إعطاء الوَرِق والذهب، وخيرٍ لكم من أن تَلقَوْا أعداءَكم فتضربوا أعناقَهم، ويضربوا أعناقَكم؟»، قالوا: بلى، قال: «ذكرُ الله».', 0, 'فضائل ذكر الله عز وجل. (ص16)', '', '', 'وعن أبي الدرداء رضي الله عنه أن رسول الله قال «ألا أخبركم بخير أعمالكم وأرفعها في درجاتكم وأزكاها عند مليككم وخير لكم من إعطاء الورق والذهب وخير لكم من أن تلقوا أعداءكم فتضربوا أعناقهم ويضربوا أعناقكم » قالوا بلى قال «ذكر الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1680, 104, 9, 'وقال عبدُ الله بن بُسْرٍ رضي الله عنه: يا رسولَ الله، أيُّ الأعمال أفضل؟ قال: «أن تفارقَ الدنيا ولسانُكَ رَطبٌ من ذكر الله».', 0, 'فضائل ذكر الله عز وجل. (ص16)', '', '', 'وقال عبد الله بن بسر رضي الله عنه يا رسول الله أي الأعمال أفضل قال «أن تفارق الدنيا ولسانك رطب من ذكر الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1681, 104, 10, 'وعن أبي هريرة رضي الله عنه قال: سمعتُ رسولَ الله ﷺ يقول: «ثلاثةٌ لا يُرَدُّ دعاؤهم: الذاكر اللهَ كثيرًا، ودعوة المظلوم، والإمام المُقسِط».', 0, 'فضائل ذكر الله عز وجل. (ص16)', '', '', 'وعن أبي هريرة رضي الله عنه قال سمعت رسول الله يقول «ثلاثة لا يرد دعاؤهم الذاكر الله كثيرا ودعوة المظلوم والإمام المقسط»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1682, 104, 11, 'ورُوِيَ عن معاذِ بْنِ جبلٍ رضي الله عنه مرفوعًا: «ما عَمِلَ آدميٌّ قطُّ عملًا أنْجَى له مِن عذابِ اللهِ؛ مِنْ ذِكرِ اللهِ تعالى».', 0, 'فضائل ذكر الله عز وجل. (ص16)', '', '', 'وروي عن معاذ بن جبل رضي الله عنه مرفوعا «ما عمل آدمي قط عملا أنجى له من عذاب الله من ذكر الله تعالى»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1683, 104, 12, 'لا بُدَّ من تَلَفُّظِ اللِّسانِ بالذِّكر:', 0, '(ص17)', '', '', 'لا بد من تلفظ اللسان بالذكر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1684, 104, 13, 'قال النووي رحمه الله: «اعلم أنَّ الأذكار المشروعة في الصلاةِ وغيرها، واجبةً كانت أو مستحبة، لا يُحسَبُ شيءٌ منها، ولا يُعتَدُّ به حتى يَتَلَفَّظَ به، بحيث يُسمِعُ نفسَه، إذا كان صحيحَ السمع لا عارضَ له».اهـ.', 0, 'لا بد من تلفظ اللسان بالذكر: (ص17)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1685, 104, 14, 'وقال الجزري في «العدة»: «ولا يُعتد له بشيء مما رتَّبه الشارعُ على قوله حتى يتلفظ به، ويُسمِعَ نفسَه».اهـ.', 0, 'لا بد من تلفظ اللسان بالذكر: (ص17)', '', '', 'وقال الجزري في «العدة» «ولا يعتد له بشيء مما رتبه الشارع على قوله حتى يتلفظ به ويسمع نفسه» اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1686, 104, 15, 'كذلك لا يُنَالُ ثوابُ قراءة القرآن بمجرَّدِ النَّظرِ دونَ تَلَفُّظٍ بحروفِها، بل لا بُدَّ من النطق بالقراءة، والتلفُّظ بالتلاوة لحصول الأجر، فبعضُ الناس يقرأُ القرآنَ بدونِ تحريكِ الشَّفَتين، قراءةً صامتةً، فلا يحصل بذلك على فضيلة القراءة.', 0, 'لا بد من تلفظ اللسان بالذكر: (ص17–18)', '', '', 'كذلك لا ينال ثواب قراءة القرآن بمجرد النظر دون تلفظ بحروفها بل لا بد من النطق بالقراءة والتلفظ بالتلاوة لحصول الأجر فبعض الناس يقرأ القرآن بدون تحريك الشفتين قراءة صامتة فلا يحصل بذلك على فضيلة القراءة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1687, 104, 16, 'الأدعية الراتبة توقيفيَّة لا يُزاد فيها، ولا يُنقَص منها', 0, '(ص19–20)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1688, 104, 17, 'عن سَمُرةَ بنِ جُندُبٍ رضي الله عنه عن النبيِّ ﷺ قال: «إذا حدَّثتُكُم حديثًا؛ فلا تَزيدُنَّ عَلَيَّ» الحديث، ومعناه يشملُ النهي عن الزيادة في لفظ الذكر تعبُّدًا.', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص19)', '', '', 'عن سمرة بن جندب رضي الله عنه عن النبي قال «إذا حدثتكم حديثا فلا تزيدن علي» الحديث ومعناه يشمل النهي عن الزيادة في لفظ الذكر تعبدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1689, 104, 18, 'وأنكر ابنُ عمرَ رضي الله عنهما على مَن زاد الصلاةَ على النبي ﷺ بعد الحمد عَقِبَ العُطاس، بحجة أنه مخالف لتعليمه ﷺ، وقال له: «وأنا أقول: الحمد لله، والسلام على رسول الله ﷺ، ولكن ليس هكذا علَّمنا رسولُ الله ﷺ، علَّمنا إذا عَطَسَ أحدُنا أن يقولَ: الحمد لله على كلِّ حال».', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص19–20)', '', '', 'وأنكر ابن عمر رضي الله عنهما على من زاد الصلاة على النبي بعد الحمد عقب العطاس بحجة أنه مخالف لتعليمه وقال له «وأنا أقول الحمد لله والسلام على رسول الله ولكن ليس هكذا علمنا رسول الله علمنا إذا عطس أحدنا أن يقول الحمد لله على كل حال»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1690, 104, 19, 'وعلَّمَ النبيُّ ﷺ البراءَ بنَ عازبٍ رضي الله عنه دعاءً يقوله عند النوم، وفي آخره: «اللهم آمنتُ بكتابك الذي أنزلتَ، وبنبيك الذي أرسلتَ»، يقول البراء: فَرَدَّدْتُها على النبيِّ ﷺ، فلمَّا بلغتُ: «اللهم آمنتُ بكتابك الذي أنزلت»، قلتُ: ورسولِك، قال: «ونبيك الذي أرسلت»، فهذا يدلُّ على عدمِ جواز تبديل ألفاظ الأذكار المأثورة؛ لأنها توقيفية، ولها خصائص وأسرار لا يدخلها القياس.', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص20–21)', '', '', 'وعلم النبي البراء بن عازب رضي الله عنه دعاء يقوله عند النوم وفي آخره «اللهم آمنت بكتابك الذي أنزلت وبنبيك الذي أرسلت» يقول البراء فرددتها على النبي فلما بلغت «اللهم آمنت بكتابك الذي أنزلت» قلت ورسولك قال «ونبيك الذي أرسلت» فهذا يدل على عدم جواز تبديل ألفاظ الأذكار المأثورة لأنها توقيفية ولها خصائص وأسرار لا يدخلها القياس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1691, 104, 20, 'قال النووي رحمه الله: «...واختار المازَري أنَّ سبب الإنكار أنَّ هذا ذكرٌ ودعاء، فينبغي فيه الاقتصار على اللفظ بحروفه».', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص21)', '', '', 'قال النووي رحمه الله « واختار المازري أن سبب الإنكار أن هذا ذكر ودعاء فينبغي فيه الاقتصار على اللفظ بحروفه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1692, 104, 21, 'فمِن هُنا شبَّه الصحابةُ تعليمَ النبيِّ ﷺ إيَّاهم بعضَ الأدعيةِ بتعليمه إيَّاهم القرآن، ووجه الشبه هنا أنها تُحفَظ وتُنقَل نقلًا حرفيًّا، ولا تُغيَّر ولا تُبدَّل.', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص21)', '', '', 'فمن هنا شبه الصحابة تعليم النبي إياهم بعض الأدعية بتعليمه إياهم القرآن ووجه الشبه هنا أنها تحفظ وتنقل نقلا حرفيا ولا تغير ولا تبدل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1693, 104, 22, 'ففي حديث الاستخارة: «كان رسول الله ﷺ يعلمنا الاستخارةَ في الأمور كلِّها كما يعلمنا السورةَ من القرآن»، وقال ابنُ مسعودٍ رضي الله عنه: «عَلَّمَني رسولُ الله ﷺ التشهُّدَ، وكَفِّي بين كَفَّيْهِ، كما يُعَلِّمُني السورةَ من القرآن».', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص21)', '', '', 'ففي حديث الاستخارة «كان رسول الله يعلمنا الاستخارة في الأمور كلها كما يعلمنا السورة من القرآن» وقال ابن مسعود رضي الله عنه «علمني رسول الله التشهد وكفي بين كفيه كما يعلمني السورة من القرآن»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1694, 104, 23, 'وفي حديث ابن عبَّاسٍ رضي الله عنهما، أنَّ رسولَ الله ﷺ كان يعلمهم هذا الدعاء كما يعلمهم السورةَ من القرآن، يقول: «اللهم إني أعوذ بك من عذاب جهنم...» الحديث.', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص22)', '', '', 'وفي حديث ابن عباس رضي الله عنهما أن رسول الله كان يعلمهم هذا الدعاء كما يعلمهم السورة من القرآن يقول «اللهم إني أعوذ بك من عذاب جهنم » الحديث', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1695, 104, 24, 'وقد قيلَ في وجه هذا التشبيه: إنَّ ذلك في تحفُّظ حروفه، وترتيب كلماته، ومنع الزيادة والنقص منه، والدرس له، والمحافظة عليه.', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص22)', '', '', 'وقد قيل في وجه هذا التشبيه إن ذلك في تحفظ حروفه وترتيب كلماته ومنع الزيادة والنقص منه والدرس له والمحافظة عليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1696, 104, 25, 'وقد طلب بعضُ الصحابةِ رضي الله عنهم من رسول الله ﷺ -أفصحِ مَنْ نَطَقَ بالضَّاد، الذي أُوتِيَ جوامعَ الكَلِم- أن يُعَلِّمَهم ما يدعون به من الصِّيَغ، ولم يَدْعُوا من تلقاء أنفسهم، مع أنهم كانوا الغايةَ في الفصاحة والبلاغة؛ لأنهم عِلِموا أنَّ الدعاء عبادةٌ تحتاجُ توقيفًا من النبي ﷺ.', 0, 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص22–23)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1697, 104, 26, 'من نصوص العلماء في الحثِّ على المأثور وعدم الابتداع في الأذكار والأدعية', 0, '(ص23)', '', '', 'من نصوص العلماء في الحث على المأثور وعدم الابتداع في الأذكار والأدعية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1698, 104, 27, 'قال الإمام أبو بكر محمد بن الوليد الطُّرْشوشي (ت ٥٢٠هـ) رحمه الله: «ومن العجب العُجاب أن تُعْرِضَ عن الدعوات التي ذكرها الله في كتابه عن الأنبياء، والأولياء، والأصفياء، مقرونةً بالإجابة، ثم تنتقيَ ألفاظَ الشعراء والكُتَّاب كأنَّك قد دعوتَ في زعمِك بجميع دعواتهم، ثم استعنتَ بدعواتِ مَنْ سواهم».اهـ.', 0, 'من نصوص العلماء في الحث على المأثور وعدم الابتداع في الأذكار والأدعية. (ص23)', '', '', 'قال الإمام أبو بكر محمد بن الوليد الطرشوشي ت ٥٢٠ه رحمه الله «ومن العجب العجاب أن تعرض عن الدعوات التي ذكرها الله في كتابه عن الأنبياء والأولياء والأصفياء مقرونة بالإجابة ثم تنتقي ألفاظ الشعراء والكتاب كأنك قد دعوت في زعمك بجميع دعواتهم ثم استعنت بدعوات من سواهم» اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1012, 104, 28, 'وقال القاضي عياض رحمه الله (ت ٥٤٤هـ): «إنَّ الله أَذِنَ في دعائه، وعَلَّمَ الدعاء في كتابه لخليقته، وعَلَّمَ النبيُّ ﷺ الدعاءَ لأمته، واجتمعت فيه ثلاثةُ أشياءَ: العلمُ بالتوحيد، والعلمُ باللغة، والنصيحة لأُمَّته، فلا ينبغي لأحدٍ أن يعدِلَ عن دعائه ﷺ.
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1007, 104, 29, 'وقال شيخ الإسلام أحمد بن تيميَّةَ (ت ٧٢٨هـ) رحمه الله: «لا ريبَ أنَّ الأذكارَ والدعواتِ من أفضلِ العبادات، والعباداتُ مبناها على التوقيف والاتباع، لا على الهوى والابتداع، فالأدعيةُ والأذكار النبويَّةُ هي أفضل ما يتحرَّاه المتحرِّي من الذكر والدعاء، وسالِكُها على سبيلِ أمانٍ وسلامةٍ، والفوائدُ التي تحصل بها لا يُعَبَّرُ عنها لسان، ولا يُحيط بها إنسان، وما سواها من الأذكار قد يكونُ محرَّمًا، وقد يكون مكروهًا، وقد يكون فيه شركٌ مما لا يَهتدي إليه أكثرُ الناس، وهي جملة يطول تفصيلها.
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1699, 104, 30, 'وقال ذَهَبِيُّ العصرِ العلَّامةُ المجدد عبدُ الرحمن بن يحيى المُعلِّمي اليماني (ت ١٣٨٦هـ) رحمه الله: «وما أخسرَ صفقةَ مَن يدَعُ الأدعيةَ الثابتة في كتابِ الله عز وجل أو في سُنَّةِ رسوله ﷺ فلا يكادُ يدعو بها! ثم يعمَدُ إلى غيرها فيتحرَّاه ويواظب عليه، أليس هذا من الظلم والعدوان؟!».', 0, 'من نصوص العلماء في الحث على المأثور وعدم الابتداع في الأذكار والأدعية. (ص26)', '', '', 'وقال ذهبي العصر العلامة المجدد عبد الرحمن بن يحيى المعلمي اليماني ت ١٣٨٦ه رحمه الله «وما أخسر صفقة من يدع الأدعية الثابتة في كتاب الله عز وجل أو في سنة رسوله فلا يكاد يدعو بها! ثم يعمد إلى غيرها فيتحراه ويواظب عليه أليس هذا من الظلم والعدوان !»', '', '');
